\rules only html
<$list filter="[{$:/temp/HUWiki/AuthorReadingMode}match[reading]]" variable="forgeReaderMode">
/* Forge adaptation 2026-11-14: reversible guest view, native Save and Control Panel retained. */
/* HUWiki derivative of Eric L. Shulman TiddlyTools/Stylesheet/ReadOnly. CC BY-NC-SA 4.0.
Original documentation and revision history: $:/HUWiki/ReaderLicense.
Source: https://tiddlytools.com/#TiddlyTools%2FStylesheet%2FReadOnly */
.authortools {display:none!important;}
.readertools {display:inline!important;}
*[class="tc-btn-TiddlyTools%2FSaveChanges"] {display:none!important;}
*[class~="tc-btn-%24%3A%2Fcore%2Fui%2FButtons%2Fnew-tiddler"] {display:none!important;}
*[class~="tc-btn-%24%3A%2Fcore%2Fui%2FButtons%2Fnew-journal"] {display:none!important;}
*[class~="tc-btn-%24%3A%2Fcore%2Fui%2FButtons%2Fnew-image"] {display:none!important;}
*[class~="tc-btn-%24%3A%2Fcore%2Fui%2FButtons%2Fnew-here"] {display:none!important;}
*[class~="tc-btn-%24%3A%2Fcore%2Fui%2FButtons%2Fnew-journal-here"] {display:none!important;}
*[class~="tc-btn-%24%3A%2Fcore%2Fui%2FButtons%2Fclone"] {display:none!important;}
*[class~="tc-btn-%24%3A%2Fcore%2Fui%2FButtons%2Fedit"] {display:none!important;}
*[class~="tc-btn-%24%3A%2Fcore%2Fui%2FButtons%2Fdelete"] {display:none!important;}
*[class~="tc-btn-%24%3A%2Fcore%2Fui%2FButtons%2Ftimestamp"] {display:none!important;}
*[class~="tc-btn-%24%3A%2Fcore%2Fui%2FButtons%2Fmanager"] {display:none!important;}
*[class~="tc-btn-%24%3A%2Fcore%2Fui%2FButtons%2Ftag-manager"] {display:none!important;}
[data-huwiki-reader-hidden="yes"] {display:none!important;}
</$list>

/* Forge adaptation of HUWiki author reading mode, 2026-11-14.
Presentation only. Original lock control, credits and CC BY-NC-SA stylesheet retained. */
exports.name="forge-reading";
exports.platforms=["browser"];
exports.after=["startup"];
exports.synchronous=true;
exports.startup=function(){
 var state="$:/temp/HUWiki/AuthorReadingMode";
 $tw.wiki.addTiddler({title:state,text:location.protocol==="file:"?"editing":"reading"});
 $tw.rootWidget.addEventListener("hu-toggle-author-reading",function(){
  var next=$tw.wiki.getTiddlerText(state)==="reading"?"editing":"reading";
  if(next==="reading" && $tw.wiki.filterTiddlers("[has[draft.of]]").length)return false;
  $tw.wiki.addTiddler({title:state,text:next});return false;
 });
};
